with recent_departments as (select * from departments where dept_name != 'Finance'), location_summary as (select location, case when budget >= 4448000 then 'high' when budget >= 1263000 then 'mid' else 'low' end as budget_bucket, round(stddev(budget), 2) as stddev_budget, max(budget) as max_budget from recent_departments group by location, case when budget >= 4448000 then 'high' when budget >= 1263000 then 'mid' else 'low' end) select location, budget_bucket, stddev_budget from location_summary where max_budget > 2816000 order by stddev_budget, location, budget_bucket limit 1
